CREATE TABLE disruptions(carrier_id text, id uuid, assignment_id uuid, expected_end timestamptz NOT NULL, reason text NOT NULL, observed_at timestamptz NOT NULL, provenance text NOT NULL, PRIMARY KEY(carrier_id,id), FOREIGN KEY(carrier_id,assignment_id) REFERENCES assignments(carrier_id,id));
CREATE TABLE stop_completions(carrier_id text, id uuid, assignment_id uuid, load_id text, stop_id text, uid text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), note text NOT NULL, PRIMARY KEY(carrier_id,id), UNIQUE(carrier_id,assignment_id,stop_id), FOREIGN KEY(carrier_id,assignment_id) REFERENCES assignments(carrier_id,id), FOREIGN KEY(carrier_id,load_id,stop_id) REFERENCES stops(carrier_id,load_id,id));
CREATE TABLE document_revisions(carrier_id text, id uuid, document_id uuid, revision integer NOT NULL, corrected_by text NOT NULL, body jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(carrier_id,id), UNIQUE(carrier_id,document_id,revision), FOREIGN KEY(carrier_id,document_id) REFERENCES documents(carrier_id,id));
